package LAB.Number;
import java.util.*;

public class CountDigits {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		
		Scanner scan = new Scanner(System.in);
		
		int n = scan.nextInt();
		
		int count = 0;
		
		while (n > 0) {
			
			count++;
			n = n/10;
			
			
		}
		System.out.print(count);
				
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		

	}

}
